int evalRPN(vector<string>& tokens) {
    vector<long long> st;
    for (auto& t : tokens) {
        if (t.size() == 1 && string("+-*/").find(t[0]) != string::npos) {
            long long b = st.back(); st.pop_back(); long long a = st.back(); st.pop_back();
            st.push_back(t[0] == '+' ? a + b : t[0] == '-' ? a - b : t[0] == '*' ? a * b : a / b);
        } else st.push_back(stoll(t));
    }
    return (int)st[0];
}
